const D = { scale: 1, energy: .62, density: .55, speed: 1, hue: 258, x: .5, y: .5, style: 'spectral', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const clp = (v,a,b) => v<a?a:(v>b?b:v);
const seedI = P.seed | 0;

// ---- coarse integer grid (scale -> cell coarseness). Small on purpose: crisp nearest-neighbor blocks ----
const GW = clp(Math.round(220 / (0.6 + clp(P.scale,0.4,2.6))), 56, 200) | 0;
const GH = clp(Math.round(GW * height / Math.max(1,width)), 40, 200) | 0;
const cells = GW * GH;
const cx = clp(Math.round(GW * clp(P.x,0.15,0.85)), 1, GW-2) | 0;
const cy = clp(Math.round(GH * clp(P.y,0.15,0.85)), 1, GH-2) | 0;

// ---- (re)build the persistent, always-fully-relaxed pile on size / seed change ----
const key = GW + 'x' + GH + '_' + seedI;
if (!S.grid || S.key !== key) {
  S.key = key;
  S.grid = new Int32Array(cells);
  S.stack = new Int32Array(cells);
  S.inS = new Uint8Array(cells);
  S.lut = new Uint8Array(12);
  S.N = 0; S.acc = 0; S.sat = 0; S.fade = 0;
  S.g = createGraphics(GW, GH); S.g.pixelDensity(1);
  S.fg = createGraphics(GW, GH); S.fg.pixelDensity(1);
  const fr = i => { const s = Math.sin(i*127.1 + seedI*311.7) * 43758.5453; return s - Math.floor(s); };
  // seed>0 -> 4-fold-symmetric extra pour sources (preserve square symmetry, still crisp)
  S.off = [[0,0,1.0]];
  if (seedI !== 0) {
    const ns = 1 + (fr(1)*2 | 0);
    for (let k = 0; k < ns; k++) {
      const ox = ((0.1 + fr(k*3+2)*0.26) * GW) | 0, oy = ((0.1 + fr(k*3+3)*0.26) * GH) | 0, w = 0.35 + fr(k*3+4)*0.45;
      S.off.push([ox,oy,w],[-ox,oy,w],[ox,-oy,w],[-ox,-oy,w]);
    }
  }
}

// ---- clock-driven pour (K.t motion floor via the perpetually expanding frontier) ----
const secF = K.section | 0;
const expo = 0.5 + clp(P.energy,0,1)*0.55 + K.intensity*0.2 + 0.08*Math.sin(K.t*0.55) + A.rms*0.5 + A.bass*0.18;
const pourF = (2 + clp(P.density,0,1)*18) * (0.4 + clp(P.speed,0,3)*0.6) * (0.6 + K.intensity*0.7) * (1 + A.bass*1.2);
S.acc += pourF;
let pn = S.acc | 0; if (pn > 1200) pn = 1200; S.acc -= pn;
const grid = S.grid;
let added = 0;
if (pn > 0) for (let s = 0; s < S.off.length; s++) {
  const o = S.off[s];
  const gx = clp(cx + o[0], 1, GW-2) | 0, gy = clp(cy + o[1], 1, GH-2) | 0;
  const q = Math.max(1, (pn * o[2]) | 0);
  grid[gy*GW + gx] += q; added += q;
}
S.N += added;

// ---- relax to COMPLETION (stack drain; inS flag prevents duplicates so a cells-sized stack suffices) ----
const st = S.stack, inS = S.inS;
let sp = 0, lost = 0;
const enq = n => { if (!inS[n]) { inS[n] = 1; st[sp++] = n; } };
if (pn > 0) for (let s = 0; s < S.off.length; s++) {
  const o = S.off[s];
  const gx = clp(cx + o[0], 1, GW-2) | 0, gy = clp(cy + o[1], 1, GH-2) | 0;
  const idx = gy*GW + gx; if (grid[idx] >= 4) enq(idx);
}
let guard = 0;
while (sp > 0 && guard < 6000000) {
  const idx = st[--sp]; inS[idx] = 0;
  const h = grid[idx];
  if (h < 4) continue;
  const times = h >> 2;                 // Abelian batch topple: floor(h/4) times at once
  grid[idx] = h - times*4;
  const y = (idx / GW) | 0, x = idx - y*GW;
  if (x > 0)      { const n = idx-1;  grid[n] += times; if (grid[n] >= 4) enq(n); } else lost += times;
  if (x < GW-1)   { const n = idx+1;  grid[n] += times; if (grid[n] >= 4) enq(n); } else lost += times;
  if (y > 0)      { const n = idx-GW; grid[n] += times; if (grid[n] >= 4) enq(n); } else lost += times;
  if (y < GH-1)   { const n = idx+GW; grid[n] += times; if (grid[n] >= 4) enq(n); } else lost += times;
  guard++;
}
S.N -= lost; if (S.N < 0) S.N = 0;

// ---- soft rebloom: once the pile saturates (inflow ~ outflow), crossfade to a fresh bloom (well past validation) ----
if (added > 0 && lost >= added*0.6) S.sat += 1; else S.sat = Math.max(0, S.sat - 2);
if (S.sat > 340 && S.fade <= 0) {
  S.fg.image(S.g, 0, 0, GW, GH);        // snapshot last frame's render for the crossfade
  S.fade = 1;
  grid.fill(0); S.N = 0; S.sat = 0; S.acc = 0;
}

// ---- HARD 4-colour LUT (no interpolation, no dither, no per-cell noise) ----
const hueShift = (P.hue - 258) + secF*7;    // slow section palette drift = dramaturgy
const OUT = [0,0,0];
function hsv(o,h,s,v){ h=((h%360)+360)%360; if(v<0)v=0; if(v>1)v=1; if(s<0)s=0; if(s>1)s=1;
  const c=v*s, x=c*(1-Math.abs((h/60)%2-1)), m=v-c; let r,g,b;
  if(h<60){r=c;g=x;b=0;} else if(h<120){r=x;g=c;b=0;} else if(h<180){r=0;g=c;b=x;}
  else if(h<240){r=0;g=x;b=c;} else if(h<300){r=x;g=0;b=c;} else {r=c;g=0;b=x;}
  o[0]=(r+m)*255; o[1]=(g+m)*255; o[2]=(b+m)*255; }
const style = P.style;
const isNeon = (style==='neon-edge' || style==='neon-contour' || style==='neon');
let RAMP;
if (style==='thermal') RAMP=[[20,0.85,0.14],[8,1.0,0.5],[34,1.0,0.85],[46,0.22,1.0]];
else if (style==='copper-oxide'||style==='copper') RAMP=[[192,0.55,0.16],[168,0.62,0.42],[134,0.5,0.66],[24,0.82,0.82]];
else if (style==='grayscale'||style==='mono'||style==='grayscale-topographic') RAMP=[[0,0,0.14],[0,0,0.40],[0,0,0.66],[0,0,0.95]];
else RAMP=[[250,0.72,0.35],[221,0.85,0.60],[46,0.9,0.87],[48,0.16,0.95]]; // spectral: indigo/blue/gold/white
const LUT = S.lut;
for (let hI=0; hI<4; hI++){ const r=RAMP[hI]; hsv(OUT, r[0]+hueShift*(hI>0?1:0.4), r[1], r[2]*expo); LUT[hI*3]=OUT[0]; LUT[hI*3+1]=OUT[1]; LUT[hI*3+2]=OUT[2]; }

// ---- render exact heights 0..3 into the coarse buffer ----
const g = S.g; g.loadPixels(); const px = g.pixels;
if (isNeon) {                              // ABSTRACT: only the nested-square height boundaries glow
  hsv(OUT, 250+hueShift, 0.7, clp(0.11*Math.max(0.7,expo*0.8),0,1)); const gr=OUT[0],gg=OUT[1],gb=OUT[2];
  const LC0=[0,0,0],LC1=[0,0,0],LC2=[0,0,0];
  hsv(OUT,196+hueShift,0.9, clp(0.55*expo,0,1)); LC0[0]=OUT[0];LC0[1]=OUT[1];LC0[2]=OUT[2];
  hsv(OUT,300+hueShift,0.85,clp(0.72*expo,0,1)); LC1[0]=OUT[0];LC1[1]=OUT[1];LC1[2]=OUT[2];
  hsv(OUT,48+hueShift,0.45, clp(0.96*expo,0,1)); LC2[0]=OUT[0];LC2[1]=OUT[1];LC2[2]=OUT[2];
  const LC=[null,LC0,LC1,LC2];
  for (let j=0;j<GH;j++) for (let i=0;i<GW;i++){
    const idx=j*GW+i; let hc=grid[idx]; if(hc<0)hc=0; else if(hc>3)hc=3;
    let lvl=0;
    if(i<GW-1){ let rn=grid[idx+1]; if(rn<0)rn=0; else if(rn>3)rn=3; if(rn!==hc){ const m=rn>hc?rn:hc; if(m>lvl)lvl=m; } }
    if(j<GH-1){ let dn=grid[idx+GW]; if(dn<0)dn=0; else if(dn>3)dn=3; if(dn!==hc){ const m=dn>hc?dn:hc; if(m>lvl)lvl=m; } }
    const o=4*idx;
    if(lvl>0){ const c=LC[lvl]||LC2; px[o]=c[0];px[o+1]=c[1];px[o+2]=c[2]; }
    else { px[o]=gr;px[o+1]=gg;px[o+2]=gb; }
    px[o+3]=255;
  }
} else {                                   // FILL: hard 4-colour ramp, exact per-cell, zero blending
  for (let idx=0; idx<cells; idx++){
    let hc=grid[idx]; if(hc<0)hc=0; else if(hc>3)hc=3;
    const b=hc*3, o=4*idx;
    px[o]=LUT[b]; px[o+1]=LUT[b+1]; px[o+2]=LUT[b+2]; px[o+3]=255;
  }
}
g.updatePixels();

// ---- draw upscaled NEAREST-neighbor (crisp edges); alpha<100 = translucent for VJ compositing ----
push();
drawingContext.imageSmoothingEnabled = false;
if (P.alpha < 100) tint(0,0,100,P.alpha);
image(g, 0, 0, width, height);
if (S.fade > 0) { tint(0,0,100, S.fade * (P.alpha<100?P.alpha:100)); image(S.fg, 0, 0, width, height); S.fade -= 0.02; if(S.fade<0)S.fade=0; }
drawingContext.imageSmoothingEnabled = true;
pop();

// ---- audio reactivity ON TOP of the clk baseline (all-zero during validation); partial, never full-frame ----
if (A.bass > 0.01 || A.treble > 0.01) {
  push(); blendMode(ADD); noStroke();
  const px0 = (cx + 0.5)/GW*width, py0 = (cy + 0.5)/GH*height, rr = Math.min(width,height)*(0.1 + A.rms*0.4);
  fill((P.hue+30)%360, 40, 100, A.bass*P.energy*12); ellipse(px0, py0, rr, rr);
  fill((P.hue+50)%360, 22, 100, A.treble*13); ellipse(px0, py0, rr*1.9, rr*1.9);
  blendMode(BLEND); pop();
}
